Here is the commit message:
gpio: loongson-64bit: Fix incorrect NULL check after
 devm_kcalloc()

Fix incorrect NULL check in loongson_gpio_init_irqchip().
The function checks chip->parent instead of chip->irq.parents.

Fixes: 03c146cb6cd1 ("gpio: loongson-64bit: Add support for Loongson-2K0300 SoC")
Signed-off-by: Chen Ni <nichen@iscas.ac.cn>
Link: https://patch.msgid.link/20260205072649.3271158-1-nichen@iscas.ac.cn
Signed-off-by: Bartosz Golaszewski <bartosz.golaszewski@oss.qualcomm.com>

Here is the root cause:
Incorrect NULL check due to a copy-paste error; the code erroneously checked `chip->parent` instead of `chip->irq.parents` after allocating memory for the latter, allowing a potential null pointer dereference if the allocation failed.

Here is the patch:

 static int loongson_gpio_init_irqchip(struct platform_device *pdev,
 				      struct loongson_gpio_chip *lgpio)
 {
 	const struct loongson_gpio_chip_data *data = lgpio->chip_data;
 	struct gpio_chip *chip = &lgpio->chip.gc;
 	int i;

 	chip->irq.default_type = IRQ_TYPE_NONE;
 	chip->irq.handler = handle_bad_irq;
 	chip->irq.parent_handler = data->irq_handler;
 	chip->irq.parent_handler_data = lgpio;
 	gpio_irq_chip_set_chip(&chip->irq, data->girqchip);

 	chip->irq.num_parents = data->intr_num;
 	chip->irq.parents = devm_kcalloc(&pdev->dev, data->intr_num,
 					 sizeof(*chip->irq.parents), GFP_KERNEL);
-	if (!chip->parent)
+	if (!chip->irq.parents)
 		return -ENOMEM;

 	for (i = 0; i < data->intr_num; i++) {
 		int ret;

 		ret = platform_get_irq(pdev, i);
 		if (ret < 0)
 			return dev_err_probe(&pdev->dev, ret,
 					     "failed to get IRQ %d\n", i);
 		chip->irq.parents[i] = ret;
 	}

 	for (i = 0; i < data->intr_num; i++) {
 		writeb(0x0, lgpio->reg_base + data->inten_offset + i);
 		writeb(0x1, lgpio->reg_base + data->intclr_offset + i);
 	}

 	return 0;
 }



